import type { BrowserElementDescriptor } from "@shared/cli/browser";
import { handles } from "./handlesRegistry";

/**
 * Detects if an element ID appears to be auto-generated by a framework.
 * Used to avoid unstable selectors based on IDs like "react-123" or "ember456".
 */
function looksAutoGenerated(id: string): boolean {
  return (
    /^(ember|react|mui|css|sc-|styled-|chakra-|radix-|:r)/i.test(id) ||
    /^[a-z]{1,3}-[a-f0-9]{4,}/i.test(id) ||
    /^\d+$/.test(id)
  );
}

/**
 * Extracts all HTML attributes from an element as key-value pairs.
 */
function describeAttributes(element: Element): Record<string, string> {
  const attributes: Record<string, string> = {};
  for (const attr of element.getAttributeNames()) {
    attributes[attr] = element.getAttribute(attr) ?? "";
  }
  return attributes;
}

/**
 * Generates a stable CSS selector for an element, prioritizing semantic attributes
 * over positional selectors. Used to re-find elements after page reloads.
 *
 * Priority: ID > aria-label > name > placeholder > title > role > href > type > structural
 */
function toSelector(element: Element): string {
  const tag = element.tagName.toLowerCase();

  // 1. Stable ID (non-generated)
  if (element.id && !looksAutoGenerated(element.id)) {
    return `${tag}#${CSS.escape(element.id)}`;
  }

  // 2. ARIA label (accessibility, rarely changes)
  const ariaLabel = element.getAttribute("aria-label");
  if (ariaLabel) {
    return `${tag}[aria-label="${CSS.escape(ariaLabel)}"]`;
  }

  // 3. Name attribute (form elements)
  const name = element.getAttribute("name");
  if (name) {
    return `${tag}[name="${CSS.escape(name)}"]`;
  }

  // 4. Placeholder (inputs)
  const placeholder = element.getAttribute("placeholder");
  if (placeholder) {
    return `${tag}[placeholder="${CSS.escape(placeholder)}"]`;
  }

  // 5. Title attribute
  const title = element.getAttribute("title");
  if (title) {
    return `${tag}[title="${CSS.escape(title)}"]`;
  }

  // 6. Role + unique text for buttons/links
  const role = element.getAttribute("role");
  if (role === "button" || tag === "button" || tag === "a") {
    const text = element.textContent?.trim();
    if (text && text.length < 30 && !/\s{2,}/.test(text)) {
      if (role) {
        return `[role="${role}"]`;
      }
    }
  }

  // 7. Href for links (stable identity)
  if (tag === "a") {
    const href = element.getAttribute("href");
    if (href && !href.startsWith("javascript:") && href.length < 100) {
      return `a[href="${CSS.escape(href)}"]`;
    }
  }

  // 8. Type for inputs
  if (tag === "input") {
    const type = element.getAttribute("type") || "text";
    const parent = element.parentElement;
    if (parent) {
      const siblings = Array.from(
        parent.querySelectorAll(`input[type="${type}"]`),
      );
      if (siblings.length === 1) {
        return `input[type="${type}"]`;
      }
    }
  }

  // 9. Fallback: structural selector
  const parts: string[] = [];
  let node: Element | null = element;
  while (node && node.nodeType === Node.ELEMENT_NODE && parts.length < 5) {
    const currentNode: Element = node;
    let selector = currentNode.nodeName.toLowerCase() ?? "";
    if (currentNode.id && !looksAutoGenerated(currentNode.id)) {
      selector += "#" + CSS.escape(currentNode.id);
      parts.unshift(selector);
      break;
    }

    const parent: Element | null = currentNode.parentElement;
    if (parent) {
      const siblings = Array.from(parent.children).filter(
        (child) => child.tagName === currentNode.tagName,
      );
      if (siblings.length > 1) {
        const index = siblings.indexOf(currentNode) + 1;
        selector += ":nth-of-type(" + index + ")";
      }
    }

    parts.unshift(selector);
    node = parent;
  }

  return parts.join(" > ");
}

/**
 * Creates a complete descriptor for a DOM element, including metadata useful
 * for AI agent automation: handle, selector, bounding box, actions, and attributes.
 * Registers the element in the handles registry for later reference.
 */
export function describeElement(
  element: Element | null,
): BrowserElementDescriptor | null {
  if (!element || element.nodeType !== Node.ELEMENT_NODE) return null;

  const rect = element.getBoundingClientRect();
  const visible = rect.width > 0 && rect.height > 0;

  const selector = toSelector(element);
  const handle = handles.register(element, selector);

  // A button's `value` is form data (usually empty), not its label.
  const textValue =
    element instanceof HTMLButtonElement
      ? element.textContent?.trim() ||
        element.getAttribute("aria-label") ||
        element.value
      : "value" in element &&
          typeof (element as HTMLInputElement).value === "string"
        ? (element as HTMLInputElement).value
        : (element.textContent ?? "");

  return {
    handle,
    tag: element.tagName?.toLowerCase?.() ?? "",
    text: textValue?.slice(0, 500) ?? "",
    name: element.getAttribute("aria-label") ?? undefined,
    role: element.getAttribute("role") ?? undefined,
    attributes: describeAttributes(element),
    boundingBox: {
      x: rect.left + window.scrollX,
      y: rect.top + window.scrollY,
      width: rect.width,
      height: rect.height,
    },
    selector,
    visible,
  };
}
